        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(struct posix_acl) +
                        count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->count = count;
    entry = (struct posix_acl_entry *)posix_acl + 1;
    for (i = 0; i < count; i++, aclp++, entry++) {
